#include "4DPlugin-pdfium.h"

#pragma mark -

static void OnStart() {
    FPDF_InitLibrary();
}

static void OnExit() {
    FPDF_DestroyLibrary();
}

void PluginMain(PA_long32 selector, PA_PluginParameters params) {
    
	try
	{
        switch(selector)
        {
            case kInitPlugin :
            case kServerInitPlugin :
                OnStart();
                break;
                
            case kDeinitPlugin :
            case kServerDeinitPlugin :
                OnExit();
                break;
                
			// --- pdfium
            
			case 1 :
				pdf_to_image(params);
				break;

        }

	}
	catch(...)
	{

	}
}

#pragma mark -

static bool _object_to_path(PA_ObjectRef f, std::string& path, int type) {
 
    if(f != NULL) {
        C_TEXT pp;
        pp.setUTF8String((const uint8_t *)"platformPath", 12);
        PA_Unistring PLATFORMPATH = PA_CreateUnistring((PA_Unichar *)pp.getUTF16StringPtr());//PA_DisposeUnistring
        PA_VariableKind vk = PA_GetObjectPropertyType(f, &PLATFORMPATH);
        if(vk == eVK_Unistring) {
            PA_Variable p = PA_GetObjectProperty(f, &PLATFORMPATH);//PA_ClearVariable
            // On error p is uninitialised: neither read nor clear it. Check
            // before PA_GetStringVariable, which resets the last error.
            if(PA_GetLastError() != eER_NoErr) {
                PA_DisposeUnistring(&PLATFORMPATH);
                return false;
            }
            PA_Unistring platformPath = PA_GetStringVariable(p);
            // Copy the text now: platformPath is borrowed from p. It used to be
            // handed to cbparams[0] as well, so clearing cbparams[0] and then p
            // disposed the same string twice.
            CUTF16String path16(platformPath.fString ? platformPath.fString : (PA_Unichar *)L"",
                                platformPath.fString ? (size_t)platformPath.fLength : 0);
            PA_Variable cbparams[2];
            // eVK_Undefined: PA_CreateVariable(eVK_Unistring) allocates an
            // empty string that PA_SetStringVariable would overwrite (leak).
            cbparams[0] = PA_CreateVariable(eVK_Undefined);
            cbparams[1] = PA_CreateVariable(eVK_Longint);
            PA_Unistring argPath = PA_CreateUnistring((PA_Unichar *)path16.c_str());//owned by cbparams[0]
            PA_SetStringVariable(&cbparams[0], &argPath);
            PA_SetLongintVariable(&cbparams[1], 1/*fk platform path*/);
            PA_Variable folder = PA_ExecuteCommandByID(type, cbparams, 2);
            PA_ClearVariable(&cbparams[0]);
            PA_ClearVariable(&cbparams[1]);
            PA_ClearVariable(&p);
            
#if VERSIONMAC
            // the constructor returns no object for an invalid path
            PA_ObjectRef folderObj = PA_GetObjectVariable(folder);
            path16.clear();
            if (folderObj) {
                pp.setUTF8String((const uint8_t *)"path", 4);
                PA_Unistring PATH = PA_CreateUnistring((PA_Unichar *)pp.getUTF16StringPtr());//PA_DisposeUnistring
                PA_Variable _p = PA_GetObjectProperty(folderObj, &PATH);//PA_ClearVariable
                PA_ErrorCode err = PA_GetLastError();
                if (err == eER_NoErr && PA_GetVariableKind(_p) == eVK_Unistring) {
                    PA_Unistring posixPath = PA_GetStringVariable(_p);
                    if (posixPath.fString) {
                        path16 = CUTF16String(posixPath.fString, (size_t)posixPath.fLength);
                    }
                }
                PA_DisposeUnistring(&PATH);
                if (err == eER_NoErr) PA_ClearVariable(&_p);
            }
#endif
            // The 4D.File constructor result is owned by the plugin.
            PA_ClearVariable(&folder);
            C_TEXT t;
            t.setUTF16String(&path16);
            CUTF8String u8;
            t.copyUTF8String(&u8);
            path = std::string((const char *)u8.c_str(), u8.size());
        }
        PA_DisposeUnistring(&PLATFORMPATH);
        return (vk == eVK_Unistring);
    }
    
    return false;
}

static bool file_object_to_path(PA_ObjectRef f, std::string& path) {
    
    return _object_to_path(f, path, 1566 /*4D.File*/);
}

#pragma mark -

// Memory write callback
static void write_to_buffer(void* context, void* data, int size) {
    std::vector<unsigned char>* buf = reinterpret_cast<std::vector<unsigned char>*>(context);
    unsigned char* bytes = static_cast<unsigned char*>(data);
    buf->insert(buf->end(), bytes, bytes + size);
}

void pdf_to_image(PA_PluginParameters params) {

    PA_ObjectRef inputFile = PA_GetObjectParameter(params, 1);
    std::string inputFilePath;
    if(inputFile) {
        file_object_to_path(inputFile, inputFilePath);
    }
    
//    sLONG_PTR *pResult = (sLONG_PTR *)params->fResult;
//    PackagePtr pParams = (PackagePtr)params->fParameters;
    
    float dpi = 72.0f;
    std::string background_rgb = "0xFFFFFFFF";
    
    PA_ObjectRef options = PA_GetObjectParameter(params, 2);
    
    if(options != NULL) {
        if(ob_is_defined(options, L"dpi")) {
            dpi = ob_get_n(options, L"dpi");
        }
        
        CUTF8String u8;
        if(ob_get_a(options, L"background", &u8)) {
            if(u8 == (const uint8_t *)"none") {
                background_rgb = "0x00000000";
            }
        }
        
    }
    
    // Clamp dpi to a sane range to avoid degenerate/oversized bitmaps
    // (unclamped values can cause UB on the float->int cast, huge
    // allocations, or a zero/negative-sized bitmap).
    const float kMinDpi = 10.0f;
    const float kMaxDpi = 1200.0f;
    if(dpi < kMinDpi) dpi = kMinDpi;
    if(dpi > kMaxDpi) dpi = kMaxDpi;
    
    float scale = dpi / 72.0f;
    
    // Hard ceiling on a single page's pixel dimensions, independent of dpi
    // clamping above (a large page at max dpi can still be huge).
    const int kMaxDimensionPx = 10000;
    
    PA_CollectionRef images = PA_CreateCollection();
    
    if(inputFilePath.length() != 0) {
        FPDF_DOCUMENT doc = FPDF_LoadDocument(inputFilePath.c_str(), nullptr);
        if(doc){
            try {
                auto startTime = std::chrono::high_resolution_clock::now();//time(0);
                int count = FPDF_GetPageCount(doc);
                for(auto i = 0; i < count; ++i) {
                    FPDF_PAGE page = FPDF_LoadPage(doc, i);
                    if(page) {
                        try {
                            float page_width_pt = FPDF_GetPageWidthF(page);
                            float page_height_pt = FPDF_GetPageHeightF(page);
                            int width_px = (int)(page_width_pt * scale);
                            int height_px = (int)(page_height_pt * scale);
                            
                            bool dimensionsValid = (width_px > 0 && height_px > 0 &&
                                                     width_px <= kMaxDimensionPx &&
                                                     height_px <= kMaxDimensionPx);
                            
                            FPDF_BITMAP bitmap = dimensionsValid ?
                                FPDFBitmap_Create(width_px, height_px, 1) : nullptr;
                            
                            if(bitmap) {
                                // Base 0 automatically detects 0x, or you can pass 16 explicitly
                                unsigned int x = static_cast<unsigned int>(std::strtoul(background_rgb.c_str(), nullptr, 16));
                                FPDFBitmap_FillRect(bitmap, 0, 0, width_px, height_px, x);
                                FPDF_RenderPageBitmap(bitmap, page, 0, 0, width_px, height_px, 0, 0);
                                unsigned char* buffer = static_cast<unsigned char*>(FPDFBitmap_GetBuffer(bitmap));
                                int stride = FPDFBitmap_GetStride(bitmap);
                                // Convert BGRA -> RGBA for PNG output
                                std::vector<unsigned char> rgba((size_t)width_px * height_px * 4);
                                for (int y = 0; y < height_px; ++y) {
                                    
                                    auto now = std::chrono::high_resolution_clock::now();//time(0);
                                    auto elapsedTime = std::chrono::duration_cast<std::chrono::milliseconds>(now - startTime).count();
                                    
                                    if(elapsedTime > 100)
                                    {
                                        startTime = now;
                                        PA_YieldAbsolute();
                                    }
                                    
                                    for (int x = 0; x < width_px; ++x) {
                                        int i = y * stride + x * 4;
                                        int j = (y * width_px + x) * 4;
                                        rgba[j + 0] = buffer[i + 2]; // R
                                        rgba[j + 1] = buffer[i + 1]; // G
                                        rgba[j + 2] = buffer[i + 0]; // B
                                        rgba[j + 3] = buffer[i + 3]; // A
                                    }
                                }
                             
                                // In-memory PNG buffer
                                std::vector<unsigned char> png_data;
                                stbi_write_png_to_func(write_to_buffer,
                                                       &png_data,
                                                       width_px,
                                                       height_px,
                                                       4,
                                                       rgba.data(),
                                                       width_px * 4, dpi);
                                
                                if(!png_data.empty()) {
                                    // eVK_Undefined: eVK_Picture would allocate a value that the shallow PA_SetPictureVariable below overwrites and leaks
                                    PA_Variable v = PA_CreateVariable(eVK_Undefined);
                                    PA_Picture image = PA_CreatePicture((void *)png_data.data(), (PA_long32)png_data.size());
                                    PA_SetPictureVariable(&v, image);
                                    PA_SetCollectionElement(images, PA_GetCollectionLength(images), v);
                                    PA_ClearVariable(&v);
                                } else {
                                    PA_Variable v = PA_CreateVariable(eVK_Null);
                                    PA_SetCollectionElement(images, PA_GetCollectionLength(images), v);
                                    PA_ClearVariable(&v);
                                }
                                
                                FPDFBitmap_Destroy(bitmap);
                            } else {
                                // dimensions invalid or allocation failed
                                PA_Variable v = PA_CreateVariable(eVK_Null);
                                PA_SetCollectionElement(images, PA_GetCollectionLength(images), v);
                                PA_ClearVariable(&v);
                            }
                            
                            FPDF_ClosePage(page);
                            
                        } catch(...) {
                            // Ensure the page/document are always closed even
                            // if something above throws (e.g. std::bad_alloc
                            // on rgba for an unexpectedly large page).
                            FPDF_ClosePage(page);
                            FPDF_CloseDocument(doc);
                            throw;
                        }

                    }else{
                        PA_Variable v = PA_CreateVariable(eVK_Null);
                        PA_SetCollectionElement(images, PA_GetCollectionLength(images), v);
                        PA_ClearVariable(&v);
                    }
                }
                FPDF_CloseDocument(doc);
            } catch(...) {
                // doc/page already closed on the path that can throw above;
                // swallow here so a single bad page doesn't crash the plugin.
            }
        }//doc
    }
    
    PA_ReturnCollection(params, images);
}

